 function n(v){return isFinite(v)?v:0} function f(v,d){if(!isFinite(v))return'—';d=d===undefined?2:d;var x=Number(v);if(Math.abs(x)<1e-8)x=0;return x.toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:0})}
